            if self.biavr_enabled:
                from ragen.biavr.verify_mechanism import parse_verify_token
                verify_t, cleaned = parse_verify_token(response)
                llm_response, actions = self._parse_response(cleaned)
                if verify_t:
                    llm_response = "<VERIFY>" + llm_response
                env_inputs.append({
                    "env_id": env_id,
                    "llm_raw_response": response,
                    "llm_response": llm_response,
                    "actions": actions,
                    "verify_t": verify_t,
                })
            else:
                llm_response, actions = self._parse_response(response)
                env_inputs.append({
                    "env_id": env_id,
                    "llm_raw_response": response,
                    "llm_response": llm_response,
                    "actions": actions,
                })
        return env_inputs

